// Normalize GCal events into the /agents/family/import shape.
// GCal all-day events use a bare date in start.date/end.date; timed
// events use start.dateTime/end.dateTime. NULL start_time == all-day,
// per family_events' schema convention.
const toItem = (ev) => {
  const allDay = !ev.start.dateTime;
  const start = allDay ? ev.start.date : ev.start.dateTime;
  return {
    source: 'gcal',
    external_id: ev.id,
    title: ev.summary || '(untitled)',
    event_date: start.slice(0, 10),
    start_time: allDay ? null : start.slice(11, 16),
    end_time: allDay ? null : (ev.end && ev.end.dateTime ? ev.end.dateTime.slice(11, 16) : null),
    location: ev.location || null,
    notes: ev.description || null,
    recurrence: null,
  };
};
return [{ json: { items: $input.all().map((i) => toItem(i.json)) } }];
